// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Enum, ISafe} from "./interfaces/ISafe.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {MerkleProof} from "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";

// modified from https://github.com/safe-global/safe-modules/blob/main/modules/allowances/contracts/AllowanceModule.sol

/**
 * @title ClankerSafeErc20Spender
 * @author Modified from Safe Global's AllowanceModule
 * @notice A Safe module that enables authorized spenders to transfer tokens from Safe wallets
 * @dev This contract manages two types of spenders:
 *      1. Team spender - can transfer specific pre-approved tokens
 *      2. Token creators - individual addresses authorized per token via Merkle proof
 */
contract ClankerSafeErc20Spender is Ownable {
    /*//////////////////////////////////////////////////////////////
                                 EVENTS
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Emitted when the team spender address is updated
     * @param previousTeamSpender The previous Team spender address
     * @param newTeamSpender The new Team spender address
     */
    event SetTeamSpender(address indexed previousTeamSpender, address indexed newTeamSpender);

    /**
     * @notice Emitted when a token transfer is executed from a Safe
     * @param safe The Safe wallet from which tokens were transferred
     * @param token The token address (address(0) for ETH)
     * @param amount The amount of tokens transferred
     * @param spender The address authorized to spend the tokens
     * @param recipient The address receiving the tokens
     */
    event Transfer(
        address indexed safe,
        address indexed token,
        uint256 amount,
        address spender,
        address indexed recipient
    );

    /**
     * @notice Emitted when the token creator Merkle root is set
     * @param tokenCreatorRoot The new Merkle root for token creators
     */
    event SetTokenCreatorRoot(bytes32 tokenCreatorRoot);

    /**
     * @notice Emitted when a token creator is initialized for a specific token
     * @param token The token address for which the creator is initialized
     * @param initializer The address that called the initialization (must match Merkle proof)
     * @param creator The address set as the creator for the token
     */
    event InitializeTokenCreator(address token, address initializer, address creator);

    /**
     * @notice Emitted when a token creator is updated by the current creator
     * @param token The token address for which the creator is updated
     * @param previousCreator The previous creator address
     * @param newCreator The new creator address
     */
    event UpdateTokenCreator(address token, address previousCreator, address newCreator);

    /*//////////////////////////////////////////////////////////////
                                 ERRORS
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Thrown when an unauthorized address attempts a restricted operation
     * @param unauthorized The address that attempted the unauthorized operation
     */
    error Unauthorized(address unauthorized);

    /**
     * @notice Thrown when a sender is not authorized to spend a specific token
     * @param sender The address attempting to spend
     * @param token The token address they're not authorized for
     */
    error NotAuthorizedToSpend(address sender, address token);

    /**
     * @notice Thrown when a Safe has insufficient balance for the requested transfer
     * @param safe The Safe wallet address
     * @param token The token address (address(0) for ETH)
     * @param balance The actual balance available
     */
    error InsufficientBalance(address safe, address token, uint256 balance);

    /**
     * @notice Thrown when attempting to initialize a token creator before the root is set
     */
    error TokenCreatorRootNotSet();

    /**
     * @notice Thrown when attempting to set a token creator root that's already been set
     * @param tokenCreatorRoot The existing root that was already set
     */
    error TokenCreatorRootAlreadySet(bytes32 tokenCreatorRoot);

    /**
     * @notice Thrown when attempting to initialize a token creator that's already been initialized
     * @param token The token address
     * @param delegate The address already set as creator
     */
    error TokenCreatorAlreadyInitialized(address token, address delegate);

    /**
     * @notice Thrown when a Merkle proof verification fails
     */
    error InvalidProof();

    /*//////////////////////////////////////////////////////////////
                            STATE VARIABLES
    //////////////////////////////////////////////////////////////*/

    /// @notice The address authorized to spend team-granted tokens
    address public teamSpender;

    /// @notice Array of tokens that the team spender is authorized to transfer
    address[] public teamGrantedTokens;

    /// @notice Mapping for O(1) lookup of team-granted tokens
    mapping(address token => bool teamGranted) public teamGrantedTokensMap;

    /// @notice Merkle root containing valid token-creator pairs
    /// @dev Leaves are in the form of  keccak256(bytes.concat(keccak256(abi.encode(token, msg.sender))))
    bytes32 public tokenCreatorRoot;

    /// @notice Mapping of token addresses to their authorized creator addresses
    mapping(address token => address creator) public tokenCreator;

    /*//////////////////////////////////////////////////////////////
                              CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Initializes the contract with owner, Team spender, and granted tokens
     * @param owner_ The address that will own the contract
     * @param teamSpender_ The address authorized to spend Team-granted tokens
     * @param teamGrantedTokens_ Array of token addresses the Team spender can transfer
     */
    constructor(address owner_, address teamSpender_, address[] memory teamGrantedTokens_)
        Ownable(owner_)
    {
        teamSpender = teamSpender_;

        // setup the teamGrantedTokensMap for O(1) lookup
        for (uint256 i = 0; i < teamGrantedTokens_.length; i++) {
            teamGrantedTokensMap[teamGrantedTokens_[i]] = true;
        }
        teamGrantedTokens = teamGrantedTokens_;

        emit SetTeamSpender(address(0), teamSpender_);
    }

    /*//////////////////////////////////////////////////////////////
                          FARCASTER FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Updates the Team spender address (only callable by owner)
     * @param teamSpender_ The new Team spender address
     */
    function setTeamSpender(address teamSpender_) external onlyOwner {
        address previousTeamSpender = teamSpender;
        teamSpender = teamSpender_;
        emit SetTeamSpender(previousTeamSpender, teamSpender);
    }

    /**
     * @notice Allows the Team spender to transfer ERC20 tokens from a Safe
     * @dev Only callable by the Team spender for Team-granted tokens
     * @param safe The Safe wallet address to transfer from
     * @param token The ERC20 token address to transfer
     * @param recipient The address to receive the tokens
     * @param amount The amount of tokens to transfer
     */
    function teamTransfer(address safe, address token, address recipient, uint256 amount)
        external
    {
        if (msg.sender != teamSpender) revert Unauthorized(msg.sender);

        // verify team had the proper privileges to spend the tokens
        if (!teamGrantedTokensMap[token]) revert NotAuthorizedToSpend(teamSpender, token);

        // check the safe has enough balance to spend
        uint256 balance = IERC20(token).balanceOf(safe);
        if (balance < amount || amount == 0) revert InsufficientBalance(safe, token, balance);

        // execute the transfer function call to the spender
        _transfer(safe, token, payable(recipient), amount);

        emit Transfer(safe, token, amount, teamSpender, recipient);
    }

    /**
     * @notice Allows the Team spender to transfer all ETH from a Safe
     * @dev Only callable by the Team spender
     * @param safe The Safe wallet address to transfer from
     */
    function teamTransferEth(address safe) external {
        if (msg.sender != teamSpender) revert Unauthorized(msg.sender);

        // check the safe has a balance to spend
        uint256 balance = address(safe).balance;
        if (balance == 0) revert InsufficientBalance(safe, address(0), balance);

        // execute the transfer function call to the spender
        _transfer(safe, address(0), payable(teamSpender), balance);

        emit Transfer(safe, address(0), balance, teamSpender, teamSpender);
    }

    /*//////////////////////////////////////////////////////////////
                       TOKEN GRANTEE FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Sets the Merkle root for token creators (only callable once by owner)
     * @dev Once set, this root cannot be changed
     * @param tokenCreatorRoot_ The Merkle root containing valid token-creator pairs
     */
    function setTokenCreatorRoot(bytes32 tokenCreatorRoot_) external onlyOwner {
        if (tokenCreatorRoot != bytes32(0)) revert TokenCreatorRootAlreadySet(tokenCreatorRoot);
        tokenCreatorRoot = tokenCreatorRoot_;
        emit SetTokenCreatorRoot(tokenCreatorRoot);
    }

    /**
     * @notice Initializes a token creator using a Merkle proof
     * @dev Can only be called once per token by the address specified in the Merkle tree
     * @param token The token address to initialize a creator for
     * @param newCreator The address to set as the creator for this token
     * @param proof The Merkle proof demonstrating msg.sender is authorized for this token
     */
    function initializeTokenCreator(address token, address newCreator, bytes32[] calldata proof)
        external
    {
        // if the root is not set, revert
        if (tokenCreatorRoot == bytes32(0)) revert TokenCreatorRootNotSet();

        // team spending privilege overrides the token creator's privilege
        if (teamGrantedTokensMap[token]) revert NotAuthorizedToSpend(msg.sender, token);

        // can only be called once per token
        if (tokenCreator[token] != address(0)) {
            revert TokenCreatorAlreadyInitialized(token, tokenCreator[token]);
        }

        // can only be called by the creator specified in the root
        if (
            !MerkleProof.verifyCalldata(
                proof,
                tokenCreatorRoot,
                keccak256(bytes.concat(keccak256(abi.encode(token, msg.sender))))
            )
        ) {
            revert InvalidProof();
        }

        // set the creator for the given token
        tokenCreator[token] = newCreator;
        emit InitializeTokenCreator(token, msg.sender, newCreator);
    }

    /**
     * @notice Allows the current token creator to update the creator address
     * @dev Only callable by the current creator for the specified token
     * @param token The token address to update the creator for
     * @param newCreator The new creator address
     */
    function updateTokenCreator(address token, address newCreator) external {
        // can only be called by the token's creator
        if (tokenCreator[token] != msg.sender) revert Unauthorized(msg.sender);

        address previousCreator = tokenCreator[token];
        tokenCreator[token] = newCreator;
        emit UpdateTokenCreator(token, previousCreator, newCreator);
    }

    /**
     * @notice Allows a token creator to transfer all tokens of a specific type from a Safe
     * @dev Only callable by the authorized creator for the specified token
     * @param safe The Safe wallet address to transfer from
     * @param token The ERC20 token address to transfer
     * @param recipient The address to receive the tokens
     */
    function tokenCreatorTransfer(address safe, address token, address recipient) external {
        // if the caller is not the creator for the given token, revert
        if (tokenCreator[token] != msg.sender) revert NotAuthorizedToSpend(msg.sender, token);

        // execute the transfer function call to the
        uint256 amount = IERC20(token).balanceOf(safe);
        if (amount == 0) revert InsufficientBalance(safe, token, amount);

        _transfer(safe, token, payable(recipient), amount);

        emit Transfer(safe, token, amount, msg.sender, recipient);
    }

    /*//////////////////////////////////////////////////////////////
                         INTERNAL FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Internal function to execute token or ETH transfers from a Safe
     * @dev Uses Safe's execTransactionFromModule to execute the transfer
     * @param safe The Safe wallet address to transfer from
     * @param token The token address (address(0) for ETH)
     * @param to The recipient address
     * @param amount The amount to transfer
     */
    function _transfer(address safe, address token, address payable to, uint256 amount) private {
        if (token == address(0)) {
            // transfer ETH
            // solium-disable-next-line security/no-send
            require(
                ISafe(safe).execTransactionFromModule(to, amount, "", Enum.Operation.Call),
                "Could not execute ether transfer"
            );
        } else {
            // transfer ERC20 token
            bytes memory data = abi.encodeWithSignature("transfer(address,uint256)", to, amount);
            require(
                ISafe(safe).execTransactionFromModule(token, 0, data, Enum.Operation.Call),
                "Could not execute token transfer"
            );
        }
    }
}

