// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

contract Enum {
    enum Operation {
        Call,
        DelegateCall
    }
}

interface ISafe {
    // ==================== Events ====================

    event SafeSetup(
        address indexed initiator,
        address[] owners,
        uint256 threshold,
        address initializer,
        address fallbackHandler
    );

    event ApproveHash(bytes32 indexed approvedHash, address indexed owner);

    event SignMsg(bytes32 indexed msgHash);

    event ExecutionFailure(bytes32 indexed txHash, uint256 payment);

    event ExecutionSuccess(bytes32 indexed txHash, uint256 payment);

    event ExecutionFromModuleSuccess(address indexed module);

    event ExecutionFromModuleFailure(address indexed module);

    event EnabledModule(address indexed module);

    event DisabledModule(address indexed module);

    event AddedOwner(address indexed owner);

    event RemovedOwner(address indexed owner);

    event ChangedThreshold(uint256 threshold);

    event ChangedFallbackHandler(address indexed handler);

    event ChangedGuard(address indexed guard);

    // ==================== Setup ====================

    /**
     * @notice Sets up the initial storage of the Safe
     * @dev Can only be called once. Initializes owners, threshold, and optional modules
     * @param _owners List of Safe owners
     * @param _threshold Number of required confirmations for a Safe transaction
     * @param to Contract address for optional delegate call
     * @param data Data payload for optional delegate call
     * @param fallbackHandler Handler for fallback calls to this contract
     * @param paymentToken Token that should be used for the payment (0 is ETH)
     * @param payment Value that should be paid
     * @param paymentReceiver Address that should receive the payment (or 0 if tx.origin)
     */
    function setup(
        address[] calldata _owners,
        uint256 _threshold,
        address to,
        bytes calldata data,
        address fallbackHandler,
        address paymentToken,
        uint256 payment,
        address payable paymentReceiver
    ) external;

    // ==================== Transaction Execution ====================

    /**
     * @notice Executes a Safe transaction
     * @dev Requires signatures from threshold number of owners
     * @param to Destination address of Safe transaction
     * @param value Ether value of Safe transaction
     * @param data Data payload of Safe transaction
     * @param operation Operation type of Safe transaction
     * @param safeTxGas Gas that should be used for the Safe transaction
     * @param baseGas Gas costs that are independent of the transaction execution
     * @param gasPrice Gas price that should be used for the payment calculation
     * @param gasToken Token address (or 0 if ETH) that is used for the payment
     * @param refundReceiver Address of receiver of gas payment (or 0 if tx.origin)
     * @param signatures Packed signature data ({bytes32 r}{bytes32 s}{uint8 v})
     * @return success Boolean indicating transaction success
     */
    function execTransaction(
        address to,
        uint256 value,
        bytes calldata data,
        Enum.Operation operation,
        uint256 safeTxGas,
        uint256 baseGas,
        uint256 gasPrice,
        address gasToken,
        address payable refundReceiver,
        bytes memory signatures
    ) external payable returns (bool success);

    // ==================== Transaction Hash ====================

    /**
     * @notice Returns the chain id used by this contract
     */
    function getChainId() external view returns (uint256);

    /**
     * @notice Returns the domain separator for this contract
     */
    function domainSeparator() external view returns (bytes32);

    /**
     * @notice Returns the bytes that are hashed to be signed by owners
     * @param to Destination address
     * @param value Ether value
     * @param data Data payload
     * @param operation Operation type
     * @param safeTxGas Gas that should be used for the Safe transaction
     * @param baseGas Gas costs that are independent of the transaction execution
     * @param gasPrice Gas price that should be used for the payment calculation
     * @param gasToken Token address (or 0 if ETH) that is used for the payment
     * @param refundReceiver Address of receiver of gas payment (or 0 if tx.origin)
     * @param _nonce Transaction nonce
     * @return Transaction hash bytes
     */
    function encodeTransactionData(
        address to,
        uint256 value,
        bytes calldata data,
        Enum.Operation operation,
        uint256 safeTxGas,
        uint256 baseGas,
        uint256 gasPrice,
        address gasToken,
        address refundReceiver,
        uint256 _nonce
    ) external view returns (bytes memory);

    /**
     * @notice Returns hash to be signed by owners
     * @param to Destination address
     * @param value Ether value
     * @param data Data payload
     * @param operation Operation type
     * @param safeTxGas Gas that should be used for the Safe transaction
     * @param baseGas Gas costs for data used to trigger the safe transaction
     * @param gasPrice Gas price that should be used for the payment calculation
     * @param gasToken Token address (or 0 if ETH) that is used for the payment
     * @param refundReceiver Address of receiver of gas payment (or 0 if tx.origin)
     * @param _nonce Transaction nonce
     * @return Transaction hash
     */
    function getTransactionHash(
        address to,
        uint256 value,
        bytes calldata data,
        Enum.Operation operation,
        uint256 safeTxGas,
        uint256 baseGas,
        uint256 gasPrice,
        address gasToken,
        address refundReceiver,
        uint256 _nonce
    ) external view returns (bytes32);

    // ==================== Owner Management ====================

    /**
     * @notice Adds the owner `owner` to the Safe and updates the threshold to `_threshold`
     * @dev This can only be done via a Safe transaction
     * @param owner New owner address
     * @param _threshold New threshold
     */
    function addOwnerWithThreshold(address owner, uint256 _threshold) external;

    /**
     * @notice Removes the owner `owner` from the Safe and updates the threshold to `_threshold`
     * @dev This can only be done via a Safe transaction
     * @param prevOwner Owner that pointed to the owner to be removed in the linked list
     * @param owner Owner address to be removed
     * @param _threshold New threshold
     */
    function removeOwner(address prevOwner, address owner, uint256 _threshold) external;

    /**
     * @notice Replaces the owner `oldOwner` in the Safe with `newOwner`
     * @dev This can only be done via a Safe transaction
     * @param prevOwner Owner that pointed to the owner to be replaced in the linked list
     * @param oldOwner Owner address to be replaced
     * @param newOwner New owner address
     */
    function swapOwner(address prevOwner, address oldOwner, address newOwner) external;

    /**
     * @notice Changes the threshold of the Safe to `_threshold`
     * @dev This can only be done via a Safe transaction
     * @param _threshold New threshold
     */
    function changeThreshold(uint256 _threshold) external;

    /**
     * @notice Returns the number of required confirmations for a Safe transaction
     */
    function getThreshold() external view returns (uint256);

    /**
     * @notice Returns if `owner` is an owner of the Safe
     */
    function isOwner(address owner) external view returns (bool);

    /**
     * @notice Returns array of owners
     */
    function getOwners() external view returns (address[] memory);

    // ==================== Module Management ====================

    /**
     * @notice Enables the module `module` for the Safe
     * @dev This can only be done via a Safe transaction
     * @param module Module to be whitelisted
     */
    function enableModule(address module) external;

    /**
     * @notice Disables the module `module` for the Safe
     * @dev This can only be done via a Safe transaction
     * @param prevModule Module that pointed to the module to be removed in the linked list
     * @param module Module to be removed
     */
    function disableModule(address prevModule, address module) external;

    /**
     * @notice Allows a Module to execute a Safe transaction without any further confirmations
     * @param to Destination address of module transaction
     * @param value Ether value of module transaction
     * @param data Data payload of module transaction
     * @param operation Operation type of module transaction
     */
    function execTransactionFromModule(
        address to,
        uint256 value,
        bytes memory data,
        Enum.Operation operation
    ) external returns (bool success);

    /**
     * @notice Allows a Module to execute a Safe transaction without any further confirmations and return data
     * @param to Destination address of module transaction
     * @param value Ether value of module transaction
     * @param data Data payload of module transaction
     * @param operation Operation type of module transaction
     */
    function execTransactionFromModuleReturnData(
        address to,
        uint256 value,
        bytes memory data,
        Enum.Operation operation
    ) external returns (bool success, bytes memory returnData);

    /**
     * @notice Returns if an module is enabled
     */
    function isModuleEnabled(address module) external view returns (bool);

    /**
     * @notice Returns array of modules
     * @param start Start of the page
     * @param pageSize Maximum number of modules that should be returned
     */
    function getModulesPaginated(address start, uint256 pageSize)
        external
        view
        returns (address[] memory array, address next);

    // ==================== Guard Management ====================

    /**
     * @notice Set a guard that checks transactions before execution
     * @dev This can only be done via a Safe transaction
     * @param guard The address of the guard to be used or the 0 address to disable the guard
     */
    function setGuard(address guard) external;

    // ==================== Fallback Manager ====================

    /**
     * @notice Set Fallback Handler to `handler` for the Safe
     * @dev Only fallback calls without value and with data will be forwarded
     * @param handler contract to handle fallbacks
     */
    function setFallbackHandler(address handler) external;

    // ==================== Signature Management ====================

    /**
     * @notice Marks a hash as approved. This can be used to validate a hash that is used by a signature
     * @param hashToApprove The hash that should be marked as approved for signatures that are verified by this contract
     */
    function approveHash(bytes32 hashToApprove) external;

    /**
     * @notice Marks a message as signed
     * @param _data Arbitrary length data that should be marked as signed on the behalf of address(this)
     */
    function signMessage(bytes calldata _data) external;

    /**
     * @notice Returns hash of a message that can be signed by owners
     * @param message Message that should be hashed
     */
    function getMessageHash(bytes memory message) external view returns (bytes32);

    /**
     * @notice Returns the bytes that are hashed to be signed by owners
     * @param message Message that should be hashed
     */
    function encodeMessageData(bytes memory message) external view returns (bytes memory);

    /**
     * @notice Checks whether the signature provided is valid for the provided data, hash
     * @param dataHash Hash of the data (could be either a message hash or transaction hash)
     * @param data That should be signed (this is passed to an external validator contract)
     * @param signatures Signature data that should be verified
     * @param requiredSignatures Amount of required valid signatures
     */
    function checkSignatures(
        bytes32 dataHash,
        bytes memory data,
        bytes memory signatures,
        uint256 requiredSignatures
    ) external view;

    /**
     * @notice Checks whether the signature provided is valid for the provided data and hash
     * @dev Since the EIP-1271 does an external call, be mindful of reentrancy attacks
     * @param dataHash Hash of the data (could be either a message hash or transaction hash)
     * @param data That should be signed (this is passed to an external validator contract)
     * @param signatures Signature data that should be verified
     */
    function checkNSignatures(
        bytes32 dataHash,
        bytes memory data,
        bytes memory signatures,
        uint256 requiredSignatures
    ) external view;

    /**
     * @notice Returns the ID of the approved hash
     */
    function approvedHashes(address owner, bytes32 hash) external view returns (uint256);

    /**
     * @notice Returns the pre-image of the message hash
     */
    function signedMessages(bytes32 messageHash) external view returns (uint256);

    // ==================== Utility Functions ====================

    /**
     * @notice Returns the nonce
     */
    function nonce() external view returns (uint256);

    /**
     * @notice Reads `length` bytes of storage at `offset`
     * @param offset Offset of the data in storage
     * @param length Length of the data to read
     */
    function getStorageAt(uint256 offset, uint256 length) external view returns (bytes memory);

    /**
     * @notice Performs a delegatecall on a target contract with the given data
     * @param to Target address
     * @param data Data to send
     */
    function simulateAndRevert(address to, bytes memory data) external;
}
